const visual = {
  prepare: function (input) {
    var texts = ['单位换算表', '项目', '换算算式', '结果', '90 km/h → m/s', '90 km/h ÷ 3.6', '25.0 m/s', '换算依据：1 m/s = 3.6 km/h', '结果保留三位有效数字'];
    return texts.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var margin = Math.max(18, Math.min(vw, vh) * 0.06);
    var titleH = 42;
    var footH = 44;
    var tableW = vw - margin * 2;
    var titleSize = Math.max(16, Math.min(24, vw * 0.045));
    var headerSize = Math.max(12, Math.min(16, vw * 0.028));
    var bodySize = Math.max(13, Math.min(18, vw * 0.032));
    var col1 = tableW * 0.30;
    var col2 = tableW * 0.38;
    var col3 = tableW - col1 - col2;
    var available = Math.max(60, vh - margin * 2 - titleH - footH);
    var headerH = Math.max(30, Math.min(44, available * 0.42));
    var dataH = Math.max(42, Math.min(64, available * 0.58));
    if (headerH + dataH > available) {
      var s = available / (headerH + dataH);
      headerH *= s;
      dataH *= s;
    }
    var tableH = headerH + dataH;
    var x0 = margin;
    var y0 = margin + titleH + Math.max(0, (available - tableH) / 2);
    function line(x1, y1, x2, y2) { return visualSdk.polyline([[x1, y1], [x2, y2]]); }
    var grid = [];
    grid.push(line(x0, y0, x0 + tableW, y0));
    grid.push(line(x0, y0 + tableH, x0 + tableW, y0 + tableH));
    grid.push(line(x0, y0, x0, y0 + tableH));
    grid.push(line(x0 + tableW, y0, x0 + tableW, y0 + tableH));
    grid.push(line(x0 + col1, y0, x0 + col1, y0 + tableH));
    grid.push(line(x0 + col1 + col2, y0, x0 + col1 + col2, y0 + tableH));
    grid.push(line(x0, y0 + headerH, x0 + tableW, y0 + headerH));
    var labels = [];
    function label(x, y, text, size, weight, anchor, fill) {
      labels.push({ type: 'label', x: x, y: y, text: text, fontSize: size, fontWeight: weight || '400', textAnchor: anchor || 'middle', fill: fill || '#1f2937' });
    }
    label(vw / 2, margin + titleSize * 0.85, '单位换算表', titleSize, '700', 'middle', '#0f172a');
    var c1 = x0 + col1 / 2;
    var c2 = x0 + col1 + col2 / 2;
    var c3 = x0 + col1 + col2 + col3 / 2;
    var headerMidY = y0 + headerH / 2 + headerSize * 0.35;
    label(c1, headerMidY, '项目', headerSize, '700', 'middle', '#0f172a');
    label(c2, headerMidY, '换算算式', headerSize, '700', 'middle', '#0f172a');
    label(c3, headerMidY, '结果', headerSize, '700', 'middle', '#0f172a');
    var rowMidY = y0 + headerH + dataH / 2 + bodySize * 0.35;
    label(c1, rowMidY, '90 km/h → m/s', bodySize, '400', 'middle', '#1f2937');
    label(c2, rowMidY, '90 km/h ÷ 3.6', bodySize, '400', 'middle', '#1f2937');
    label(c3, rowMidY, '25.0 m/s', bodySize, '700', 'middle', '#0f172a');
    var noteY = y0 + tableH + Math.max(18, bodySize * 1.4);
    var noteSize = Math.max(11, bodySize * 0.85);
    label(vw / 2, noteY, '换算依据：1 m/s = 3.6 km/h', noteSize, '400', 'middle', '#475569');
    label(vw / 2, noteY + Math.max(16, bodySize * 1.2), '结果保留三位有效数字', noteSize, '400', 'middle', '#475569');
    var paths = [];
    var bg = ['M', margin * 0.5, margin * 0.5, 'L', vw - margin * 0.5, margin * 0.5, 'L', vw - margin * 0.5, vh - margin * 0.5, 'L', margin * 0.5, vh - margin * 0.5, 'Z'];
    paths.push({ id: 'bg', commands: bg });
    for (var i = 0; i < grid.length; i++) { paths.push({ id: 'grid' + i, commands: grid[i] }); }
    var children = [];
    children.push({ type: 'path', pathId: 'bg', fill: '#ffffff', stroke: 'none' });
    for (var j = 0; j < grid.length; j++) { children.push({ type: 'path', pathId: 'grid' + j, stroke: '#334155', strokeWidth: 1.2, fill: 'none' }); }
    for (var k = 0; k < labels.length; k++) { children.push(labels[k]); }
    return { schemaVersion: 1, sceneId: 'unit-conversion-table', revision: input.revision, viewBox: { x: 0, y: 0, width: vw, height: vh }, paths: paths, root: { type: 'group', children: children } };
  }
};
